<?php use App\Support\Env;use App\Support\View;$base=rtrim((string)Env::get('APP_BASE_PATH',''),'/');$action=$base.'/admin/campeonatos/'.$tournament['slug'].'/'.$module.'/competicao'; ?>
<div class="admin-layout"><aside class="sidebar"><div class="brand-mark">TG</div><strong><?=View::e($tournament['name'])?></strong><nav><?php foreach($navigation as$i):?><a class="<?=$i['key']===$module?'active':''?>" href="<?=View::e($base.$i['href'])?>"><?=View::e($i['label'])?></a><?php endforeach;?></nav></aside><main id="conteudo" class="content dashboard-page"><header class="topbar"><div><span class="eyebrow">Competicao</span><h1><?=View::e(ucfirst($module))?></h1><p class="muted">Dados persistidos do campeonato, sem identificadores tecnicos visiveis.</p></div></header>
<?php if($module==='grupos'):?><section class="panel"><h2>Novo grupo</h2><form method="post" action="<?=View::e($action)?>" class="form-grid"><input type="hidden" name="_csrf" value="<?=View::e($csrf)?><input type="hidden" name="action" value="group"><label>Fase<select name="stage_id"><?php foreach($data['stages']as$s):?><option value="<?=$s['id']?>"><?=View::e($s['name'])?></option><?php endforeach;?></select></label><label>Nome<input name="name" required></label><label>Codigo<input name="code" required maxlength="4"></label><label>Limite<input name="max_teams" type="number" min="2" value="5"></label><button class="button">Criar grupo</button></form></section><section class="panel"><h2>Distribuicao</h2><?php foreach($data['groups']as$g):?><article class="subpanel"><h3><?=View::e($g['name'])?> (<?=count($g['teams'])?>/<?=$g['max_teams']?>)</h3><p><?php foreach($g['teams']as$team)echo View::e($team['name']).' ';?></p><form method="post" action="<?=View::e($action)?>"><input type="hidden" name="_csrf" value="<?=View::e($csrf)?><input type="hidden" name="action" value="assign"><input type="hidden" name="group_id" value="<?=$g['id']?>"><select name="team_id"><?php foreach($data['teams']as$team):?><option value="<?=$team['id']?>"><?=View::e($team['name'])?></option><?php endforeach;?></select><button class="button ghost">Adicionar equipe</button></form></article><?php endforeach;?></section>
<?php elseif($module==='rodadas'||$module==='partidas'):?><section class="panel"><h2>Assistente de tabela</h2><p>Confirme grupo, turno, inicio e depois gere. O service impede confrontos duplicados.</p><?php foreach($data['groups']as$g):?><form method="post" action="<?=View::e($action)?>" class="subpanel"><input type="hidden" name="_csrf" value="<?=View::e($csrf)?><input type="hidden" name="action" value="schedule"><input type="hidden" name="group_id" value="<?=$g['id']?>"><strong><?=View::e($g['name'])?></strong><label>Primeira data<input type="datetime-local" name="start_at"></label><button class="button">Gerar previa confirmada</button></form><?php endforeach;?></section><section class="panel"><h2>Calendario</h2><div class="table-wrap"><table><thead><tr><th>Rodada</th><th>Jogo</th><th>Data</th><th>Status</th></tr></thead><tbody><?php foreach($data['matches']as$m):?><tr><td><?=View::e((string)$m['round_name'])?></td><td><?=View::e($m['home_name'].' x '.$m['away_name'])?></td><td><?=View::e((string)$m['scheduled_at'])?></td><td><?=View::e($m['status'])?></td></tr><?php endforeach;?></tbody></table></div></section>
<?php elseif($module==='classificacao'):?><section class="panel"><h2>Classificacao</h2><div class="table-wrap"><table><thead><tr><th>Pos.</th><th>Equipe</th><th>Pts</th><th>J</th><th>V</th><th>E</th><th>D</th><th>GP</th><th>GC</th><th>SG</th></tr></thead><tbody><?php foreach($data['standings']as$r):?><tr><td><?=$r['position']?></td><td><?=View::e($r['team_name'])?></td><td><?=$r['points']?></td><td><?=$r['played']?></td><td><?=$r['wins']?></td><td><?=$r['draws']?></td><td><?=$r['losses']?></td><td><?=$r['goals_for']?></td><td><?=$r['goals_against']?></td><td><?=$r['goals_for']-$r['goals_against']?></td></tr><?php endforeach;?></tbody></table></div></section>
<?php else:?><section class="panel"><h2>Mata-mata</h2><form method="post" action="<?=View::e($action)?>"><input type="hidden" name="_csrf" value="<?=View::e($csrf)?><input type="hidden" name="action" value="knockout"><button class="button">Gerar quartas conforme classificacao</button></form><div class="table-wrap"><table><thead><tr><th>Fase</th><th>Confronto</th><th>Placar</th><th>Status</th></tr></thead><tbody><?php foreach($data['matches']as$m):if($m['stage_key']==='group')continue;?><tr><td><?=View::e($m['stage_key'])?></td><td><?=View::e($m['home_name'].' x '.$m['away_name'])?></td><td><?=$m['home_score']?> x <?=$m['away_score']?></td><td><?=View::e($m['status'])?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?></main></div>
